const LOCATIONS = ['사무실','경북대','영대','동산','기타'];
const HOSPITALS = ['경북대','영대','동산','기타'];

// 위치/병원 선택값은 거래처 Master를 단일 기준으로 사용한다.
// 기존 데이터와의 호환을 위해 병원 정보가 없을 때만 기본 위치를 사용한다.
function getLocations() {
  const hospitalNames = Array.isArray(state?.hospitals)
    ? sortHospitalMaster().map(h=>String(h?.name||'').trim()).filter(Boolean)
    : [];
  const locations = hospitalNames.length ? ['사무실', ...hospitalNames] : LOCATIONS;
  return [...new Set(locations)];
}
const TX_TYPES = ['입고','사용','선납','회수','조정(+)','조정(-)'];
const STORE_KEY = 'daekyung_tracking_modular_v10';
const LEGACY_STORE_KEYS = ['daekyung_tracking_modular_v1', 'DK_STATE'];
const LOCAL_SNAPSHOT_PREFIX = 'DK_STATE_SNAPSHOT_V12::';
const STATE_SCHEMA_VERSION = 12;

function today() { return new Date().toISOString().slice(0,10); }
function money(n) { return Number(n||0).toLocaleString('ko-KR'); }
function qty(n) { return Number(n||0).toLocaleString('ko-KR'); }
function byId(id) { return document.getElementById(id); }
function clone(x) { return JSON.parse(JSON.stringify(x)); }
function download(filename, text, type='text/plain;charset=utf-8') {
  if(String(type).includes('text/csv') && !String(text).startsWith('\uFEFF')) text='\uFEFF'+text;
  const blob = new Blob([text], {type}); const a=document.createElement('a');
  a.href=URL.createObjectURL(blob); a.download=filename; a.click(); URL.revokeObjectURL(a.href);
}
function toCSV(rows) { return rows.map(r=>r.map(v=>'"'+String(v ?? '').replaceAll('"','""')+'"').join(',')).join('\n'); }
function parseNumber(v) { const n=Number(String(v ?? '').replaceAll(',','').trim()); return isNaN(n)?0:n; }
function normalizeDate(v) {
  if(!v) return today();
  if(typeof v === 'number' && window.XLSX) { const d = XLSX.SSF.parse_date_code(v); return `${d.y}-${String(d.m).padStart(2,'0')}-${String(d.d).padStart(2,'0')}`; }
  const s=String(v).trim().replace(/[.\/]/g,'-');
  const m=s.match(/(\d{4})-(\d{1,2})-(\d{1,2})/); if(m) return `${m[1]}-${m[2].padStart(2,'0')}-${m[3].padStart(2,'0')}`;
  return s;
}
function initialState() {
  const products = DEFAULT_MASTER.map((p,i)=>({
    id:p.id || `P${String(i+1).padStart(3,'0')}`, category:p.category||'미분류', name:p.name,
    purchasePrice:0, salePrices:{'경북대':0,'영대':0,'동산':0,'기타':0}, stock:p.stock||{}
  }));
  DEFAULT_PRICES.forEach(pr=>{
    const p=products.find(x=>x.id===pr.id || x.name===pr.name);
    if(p) { p.purchasePrice=Number(pr.purchase||pr.purchasePrice||0); p.salePrices['기타']=Number(pr.sale||pr.salePrice||0); }
  });
  return {
    meta:{schemaVersion:STATE_SCHEMA_VERSION, createdAt:new Date().toISOString(), updatedAt:new Date().toISOString()},
    products, transactions:[], deletedTransactionIds:[], overuses:[], history:[], hospitals:[], monthlyClosings:[], audit:{system:[], physical:[], result:[], source:''}, settings:{}
  };
}
function eventIdentitySignature(row){
  const value=row&&typeof row==='object'?row:{};
  return [value.date||'',value.location||'',value.type||'',value.productId||'',Number(value.qty||0),value.memo||'',value.status||''].join('\u001f');
}
function shortStableHash(value){
  let hash=2166136261;
  const text=String(value||'');
  for(let i=0;i<text.length;i++){hash^=text.charCodeAt(i);hash=Math.imul(hash,16777619);}
  return (hash>>>0).toString(36);
}
function ensureEventIds(rows,prefix='event'){
  const occurrences=new Map();
  return (Array.isArray(rows)?rows:[]).map(row=>{
    if(row&&row.id)return row;
    const signature=eventIdentitySignature(row);
    const occurrence=(occurrences.get(signature)||0)+1;
    occurrences.set(signature,occurrence);
    return Object.assign({},row,{id:`legacy-${prefix}-${shortStableHash(signature)}-${occurrence}`});
  });
}
function createEventId(prefix='event'){
  if(globalThis.crypto?.randomUUID)return `${prefix}-${crypto.randomUUID()}`;
  return `${prefix}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,10)}`;
}
function migrateState(raw) {
  const base = initialState();
  const src = raw && typeof raw === 'object' ? raw : {};
  const next = Object.assign(base, src);
  next.meta = Object.assign({}, base.meta, src.meta || {}, {schemaVersion:STATE_SCHEMA_VERSION});
  next.products = Array.isArray(src.products) ? src.products : base.products;
  next.transactions = ensureEventIds(Array.isArray(src.transactions) ? src.transactions : [],'tx');
  next.overuses = ensureEventIds(Array.isArray(src.overuses) ? src.overuses : [],'overuse');
  next.deletedTransactionIds = Array.isArray(src.deletedTransactionIds) ? [...new Set(src.deletedTransactionIds.map(String))] : [];
  if(next.deletedTransactionIds.length)next.transactions=next.transactions.filter(row=>!next.deletedTransactionIds.includes(String(row.id||'')));
  next.history = Array.isArray(src.history) ? src.history : [];
  next.hospitals = Array.isArray(src.hospitals) ? src.hospitals : [];
  next.monthlyClosings = Array.isArray(src.monthlyClosings) ? src.monthlyClosings : [];
  next.audit = Object.assign({system:[], physical:[], result:[], source:''}, src.audit || {});
  next.settings = Object.assign({}, src.settings || {});
  return next;
}
function recoverMissingMasterData(current){
  const recovered=current;
  for(const key of LEGACY_STORE_KEYS){
    try{
      const raw=localStorage.getItem(key); if(!raw)continue;
      const legacy=migrateState(JSON.parse(raw));
      let changed=false;
      if(!recovered.hospitals?.length && legacy.hospitals?.length){recovered.hospitals=clone(legacy.hospitals);changed=true;}
      if(!recovered.hospitalPrices?.length && legacy.hospitalPrices?.length){recovered.hospitalPrices=clone(legacy.hospitalPrices);changed=true;}
      if(changed){
        const recoveredAt=new Date().toISOString();
        recovered.meta=Object.assign({},recovered.meta||{},{updatedAt:recoveredAt,cloudDirtyAt:recoveredAt,lastSaveReason:'legacy-master-recovery'});
      }
    }catch(e){}
  }
  return recovered;
}
function importantStateScore(value){
  if(!value||typeof value!=='object')return 0;
  const audit=value.audit||{};
  return (value.hospitals?.length||0)*20+(value.transactions?.length||0)*10+(value.hospitalPrices?.length||0)*3+(value.overuses?.length||0)*5+(value.monthlyClosings?.length||0)*15+(value.history?.length||0)+(audit.system?.length||0)+(audit.physical?.length||0)+(audit.result?.length||0);
}
function mergeStateWithoutLoss(base,incoming){
  if(window.DKCloud?.safeMergeState)return migrateState(window.DKCloud.safeMergeState(base,incoming));
  return importantStateScore(incoming)>=importantStateScore(base)?migrateState(incoming):migrateState(base);
}
function recoverFromLocalSnapshots(current){
  if(current?.meta?.lastSaveReason==='reset')return current;
  let recovered=current;
  for(let slot=0;slot<10;slot++){
    try{
      const raw=localStorage.getItem(`${LOCAL_SNAPSHOT_PREFIX}${slot}`);if(!raw)continue;
      const snapshot=migrateState(JSON.parse(raw));
      if(importantStateScore(snapshot)>importantStateScore(recovered))recovered=mergeStateWithoutLoss(snapshot,recovered);
    }catch(e){}
  }
  if(importantStateScore(recovered)>importantStateScore(current)){
    const recoveredAt=new Date().toISOString();
    recovered.meta=Object.assign({},recovered.meta||{},{updatedAt:recoveredAt,cloudDirtyAt:recoveredAt,lastSaveReason:'local-snapshot-recovery'});
  }
  return recovered;
}
let state = loadState();
window.state = state;
function loadState() {
  const keys = [STORE_KEY, ...LEGACY_STORE_KEYS];
  for(const key of keys) {
    try {
      const raw = localStorage.getItem(key);
      if(raw) {
        const loaded = recoverFromLocalSnapshots(recoverMissingMasterData(migrateState(JSON.parse(raw))));
        if(key !== STORE_KEY) localStorage.setItem(STORE_KEY, JSON.stringify(loaded));
        return loaded;
      }
    } catch(e) {}
  }
  return initialState();
}
function saveState(reason='auto') {
  try {
    const previous=localStorage.getItem(STORE_KEY);
    if(previous && reason!=='reset'){
      try{
        const previousState=JSON.parse(previous);
        if(importantStateScore(previousState)>0){const slot=Math.floor(Date.now()/60000)%10;localStorage.setItem(`${LOCAL_SNAPSHOT_PREFIX}${slot}`,previous);}
      }catch(e){}
    }
    const savedAt=new Date().toISOString();
    state.meta = Object.assign({}, state.meta || {}, {schemaVersion:STATE_SCHEMA_VERSION, updatedAt:savedAt, lastSaveReason:reason, cloudDirtyAt:savedAt});
    localStorage.setItem(STORE_KEY, JSON.stringify(state));
    window.state = state;
    if(window.DKCloud) window.DKCloud.queuePush(state, reason);
    showAutosaveStatus();
    return true;
  } catch(e) {
    console.error('저장 실패', e);
    alert('브라우저 저장공간이 부족하거나 저장에 실패했습니다. JSON 백업 후 불필요한 데이터를 정리해 주세요.');
    return false;
  }
}
function addHistory(type, content, count=1) { state.history.unshift({time:new Date().toLocaleString('ko-KR'), type, content, count}); state.history=state.history.slice(0,300); saveState('history'); }
function resetCounts(){
  const inventoryRows=(state.products||[]).reduce((sum,p)=>sum+Object.values(p.stock||{}).filter(cell=>Object.values(cell||{}).some(v=>Number(v||0)!==0)).length,0);
  const pricedProducts=(state.products||[]).filter(p=>Number(p.purchasePrice||0)||Number(p.defaultSalePrice||p.salePrice||0)||Object.values(p.salePrices||{}).some(v=>Number(v||0))).length;
  return {transactions:(state.transactions||[]).length,overuses:(state.overuses||[]).length,inventory:inventoryRows,hospitals:(state.hospitals||[]).length,prices:pricedProducts+(state.hospitalPrices||[]).length};
}
function renderResetSummary(){
  const c=resetCounts();
  const map={resetTransactionCount:`${c.transactions}건 (과사용 ${c.overuses}건)`,resetInventoryCount:`${c.inventory}개 위치`,resetHospitalCount:`${c.hospitals}개 거래처`,resetPriceCount:`${c.prices}건`};
  Object.entries(map).forEach(([id,text])=>{const el=byId(id);if(el)el.textContent=text;});
}
async function confirmAndCommitReset(label,reason,mutate){
  if(!confirm(`${label}을(를) 실행할까요?\n\n대상 자료는 삭제되며 실행 직전에 JSON 백업이 자동으로 다운로드됩니다.`))return false;
  const typed=prompt(`최종 확인입니다. 계속하려면 아래 입력란에 "초기화"를 입력하세요.\n\n초기화 대상: ${label}`,'');
  if(typed!=='초기화'){if(typed!==null)alert('입력 문구가 일치하지 않아 취소했습니다.');return false;}
  if(window.DKCloud?.configured&&!navigator.onLine){alert('인터넷에 연결되어 있지 않아 Cloud 초기화를 실행할 수 없습니다. 연결 후 다시 시도해 주세요.');return false;}
  download(`daekyung_before_${reason}_${today()}.json`,JSON.stringify(state,null,2),'application/json;charset=utf-8');
  mutate();window.state=state;saveState(reason);
  Object.keys(localStorage).filter(k=>k.startsWith(LOCAL_SNAPSHOT_PREFIX)||k.startsWith('DK_FORM_DRAFT_V10::')).forEach(k=>localStorage.removeItem(k));
  let cloudSaved=true;
  if(window.DKCloud?.configured){
    cloudSaved=await DKCloud.replaceAllState(state,reason);
  }
  if(!cloudSaved){alert('Cloud 초기화 저장에 실패했습니다. 데이터 재복원을 막기 위해 새로고침하지 않습니다. 연결 상태를 확인한 뒤 다시 실행해 주세요.');return false;}
  alert(`${label}이(가) 완료되었습니다.`);location.reload();return true;
}
async function resetAll(){
  const preservedSettings=clone(state.settings||{});
  return confirmAndCommitReset('전체 초기화','reset-all',()=>{state=initialState();state.settings=preservedSettings;});
}
async function resetTransactions(){return confirmAndCommitReset('거래내역 초기화','reset-transactions',()=>{state.transactions=[];state.deletedTransactionIds=[];state.overuses=[];state.monthlyClosings=[];state.history=(state.history||[]).filter(row=>!['거래','거래등록','거래수정','거래삭제','과사용','월마감','월마감재오픈'].includes(row.type));});}
async function resetInventory(){return confirmAndCommitReset('재고 등록자료 초기화','reset-inventory',()=>{(state.products||[]).forEach(p=>Object.values(p.stock||{}).forEach(cell=>{Object.keys(cell||{}).forEach(key=>cell[key]=0);}));});}
async function resetHospitals(){return confirmAndCommitReset('거래처 Master 초기화','reset-hospitals',()=>{state.hospitals=[];state.hospitalPrices=[];});}
async function resetPrices(){return confirmAndCommitReset('단가관리 초기화','reset-prices',()=>{(state.products||[]).forEach(p=>{p.purchasePrice=0;p.defaultSalePrice=0;p.salePrice=0;p.salePrices={};});state.hospitalPrices=[];});}
function exportBackup() { download(`daekyung_backup_v11_${today()}.json`, JSON.stringify(state,null,2), 'application/json;charset=utf-8'); }
function restoreBackup(evt) { const f=evt.target.files[0]; if(!f) return; const r=new FileReader(); r.onload=()=>{ try{state=migrateState(JSON.parse(r.result)); saveState('restore'); location.reload();}catch(e){alert('JSON 파일을 확인하세요.')} }; r.readAsText(f); }
function pageDraftKey(){ return 'DK_FORM_DRAFT_V10::' + location.pathname.split('/').pop(); }
function rememberLastPage(){ try{ localStorage.setItem('DK_LAST_PAGE_V10', location.pathname.split('/').pop() || 'index.html'); }catch(e){} }
function getLastPage(){ try{return localStorage.getItem('DK_LAST_PAGE_V10') || 'index.html';}catch(e){return 'index.html';} }
function saveCurrentPageDraft(){
  const draft = {};
  document.querySelectorAll('input, select, textarea').forEach(el=>{
    if(!el.id || el.type === 'file' || el.type === 'button' || el.type === 'submit') return;
    draft[el.id] = (el.type === 'checkbox') ? el.checked : el.value;
  });
  try{ localStorage.setItem(pageDraftKey(), JSON.stringify(draft)); }catch(e){}
}
function restoreCurrentPageDraft(){
  let draft={};
  try{ draft = JSON.parse(localStorage.getItem(pageDraftKey()) || '{}'); }catch(e){}
  Object.entries(draft).forEach(([id,val])=>{ const el=byId(id); if(!el || el.type === 'file') return; if(el.type === 'checkbox') el.checked=!!val; else el.value=val; });
}
function clearCurrentPageDraft(){ try{ localStorage.removeItem(pageDraftKey()); }catch(e){} }
function setupAutoDraft(){
  restoreCurrentPageDraft();
  document.addEventListener('input', e=>{ if(e.target && e.target.matches('input,select,textarea')) saveCurrentPageDraft(); }, true);
  document.addEventListener('change', e=>{ if(e.target && e.target.matches('input,select,textarea')) saveCurrentPageDraft(); }, true);
}
function showAutosaveStatus(){
  const el=byId('autosaveStatus');
  if(el) el.textContent = '자동저장 ' + new Date().toLocaleTimeString('ko-KR', {hour:'2-digit', minute:'2-digit'});
}
window.addEventListener('beforeunload',saveCurrentPageDraft);
function productByName(name) { return state.products.find(p=>p.name===name); }
function productById(id) { return state.products.find(p=>p.id===id); }
function productOptions(select, includeAll=false) { if(!select) return; select.innerHTML=(includeAll?'<option value="">전체</option>':'')+state.products.map(p=>`<option value="${p.id}">${p.name}</option>`).join(''); }
function categoryOptions(select, includeAll=true) { if(!select) return; const cats=[...new Set(state.products.map(p=>p.category||'미분류'))].sort(); select.innerHTML=(includeAll?'<option value="">전체</option>':'')+cats.map(c=>`<option value="${c}">${c}</option>`).join(''); }
function locationOptions(select, includeAll=false) { if(!select) return; select.innerHTML=(includeAll?'<option value="">전체</option>':'')+getLocations().map(l=>`<option value="${l}">${l}</option>`).join(''); }
function refillOptions(select,fill,includeAll=false){
  if(!select)return;
  const selected=select.value;
  fill(select,includeAll);
  if([...select.options].some(o=>o.value===selected))select.value=selected;
  refreshSearchableSelect(select);
}

/* Searchable location / hospital selectors.
   The original select remains the source of truth so existing save, filter and
   change-event code continues to work without page-specific changes. */
const SEARCHABLE_LOCATION_SELECT_IDS=['mLoc','oLoc','invLoc','hpHospital','priceHospital','auditLoadLoc','closeLocation'];
const searchableSelects=new Map();
function searchableOptionLabel(select){
  const option=select.options[select.selectedIndex];
  return option?option.textContent.trim():'';
}
function closeSearchableSelects(except){
  searchableSelects.forEach((ui,select)=>{
    if(select!==except){ui.wrap.classList.remove('open');ui.trigger.setAttribute('aria-expanded','false');}
  });
}
function renderSearchableOptions(select){
  const ui=searchableSelects.get(select);if(!ui)return;
  const keyword=ui.search.value.trim().toLocaleLowerCase('ko-KR');
  const options=[...select.options].filter(option=>!option.disabled&&!option.hidden&&option.textContent.toLocaleLowerCase('ko-KR').includes(keyword));
  ui.list.innerHTML='';
  options.forEach(option=>{
    const button=document.createElement('button');
    button.type='button';button.className='searchable-select-option';
    button.textContent=option.textContent;
    button.dataset.value=option.value;
    if(option.value===select.value)button.classList.add('selected');
    button.addEventListener('click',()=>{
      select.value=option.value;
      select.dispatchEvent(new Event('change',{bubbles:true}));
      ui.trigger.value=option.textContent.trim();
      ui.wrap.classList.remove('open');ui.trigger.setAttribute('aria-expanded','false');
    });
    ui.list.appendChild(button);
  });
  if(!options.length){const empty=document.createElement('div');empty.className='searchable-select-empty';empty.textContent='검색 결과가 없습니다.';ui.list.appendChild(empty);}
}
function refreshSearchableSelect(select){
  const ui=searchableSelects.get(select);if(!ui)return;
  ui.trigger.value=searchableOptionLabel(select);
  renderSearchableOptions(select);
}
function enhanceSearchableSelect(select){
  if(!select||searchableSelects.has(select))return;
  const wrap=document.createElement('div');wrap.className='searchable-select';
  select.parentNode.insertBefore(wrap,select);wrap.appendChild(select);
  select.classList.add('searchable-native-select');
  const trigger=document.createElement('input');
  trigger.type='text';trigger.className='searchable-select-trigger';trigger.autocomplete='off';
  trigger.setAttribute('role','combobox');trigger.setAttribute('aria-haspopup','listbox');trigger.setAttribute('aria-expanded','false');
  trigger.placeholder=select.id==='auditLoadLoc'?'위치 검색':'병원 또는 위치 검색';
  const panel=document.createElement('div');panel.className='searchable-select-panel';
  const search=document.createElement('input');search.type='search';search.className='searchable-select-search';search.autocomplete='off';search.placeholder=trigger.placeholder;
  const list=document.createElement('div');list.className='searchable-select-options';list.setAttribute('role','listbox');
  panel.append(search,list);wrap.append(trigger,panel);
  searchableSelects.set(select,{wrap,trigger,panel,search,list});
  const open=()=>{closeSearchableSelects(select);wrap.classList.add('open');trigger.setAttribute('aria-expanded','true');search.value='';renderSearchableOptions(select);setTimeout(()=>search.focus(),0);};
  trigger.addEventListener('click',open);trigger.addEventListener('focus',open);
  trigger.addEventListener('input',()=>{if(!wrap.classList.contains('open'))open();search.value=trigger.value;renderSearchableOptions(select);});
  search.addEventListener('input',()=>renderSearchableOptions(select));
  search.addEventListener('keydown',event=>{
    if(event.key==='Escape'){wrap.classList.remove('open');trigger.setAttribute('aria-expanded','false');trigger.focus();}
    if(event.key==='Enter'){const first=list.querySelector('.searchable-select-option');if(first){event.preventDefault();first.click();}}
  });
  select.addEventListener('change',()=>refreshSearchableSelect(select));
  new MutationObserver(()=>setTimeout(()=>refreshSearchableSelect(select),0)).observe(select,{childList:true,subtree:true});
  refreshSearchableSelect(select);
}
function initSearchableLocationSelects(){SEARCHABLE_LOCATION_SELECT_IDS.forEach(id=>enhanceSearchableSelect(byId(id)));}
document.addEventListener('click',event=>{if(!event.target.closest('.searchable-select'))closeSearchableSelects();});
document.addEventListener('DOMContentLoaded',()=>setTimeout(initSearchableLocationSelects,0));

