window.addEventListener('dk-state-updated',refreshCurrentPageFromState);
function stockCell(p, loc) { return p.stock?.[loc] || {stock:0,current:0,in:0,use:0,prepaid:0,base:0}; }
function transactionEffectForLocation(t, loc) {
  const q = Number(t.qty || 0);
  const txLoc = t.location || '';
  const type = t.type || '';

  // 선납: 사무실 재고가 병원으로 이동한 것으로 처리
  // - 거래 위치가 병원이면 병원 현재고 증가
  // - 사무실 현재고는 같은 수량만큼 감소
  if(type === '선납') {
    if(loc === '사무실') return -q;
    if(txLoc === loc) return q;
    return 0;
  }

  // 회수: 병원 재고가 사무실로 돌아온 것으로 처리
  // - 거래 위치가 병원이면 병원 현재고 감소
  // - 사무실 현재고는 같은 수량만큼 증가
  if(type === '회수') {
    if(loc === '사무실') return q;
    if(txLoc === loc) return -q;
    return 0;
  }

  // 일반 거래: 해당 위치의 현재고를 직접 증감
  if(txLoc !== loc) return 0;
  if(['입고','조정(+)'].includes(type)) return q;
  if(['사용','조정(-)','과사용'].includes(type)) return -q;
  return 0;
}

function currentQty(p, loc='') {
  const locs = loc ? [loc] : getLocations();
  return locs.reduce((sum, l) => {
    const base = Number(stockCell(p, l).stock || 0);
    const tx = state.transactions
      .filter(t => t.productId === p.id)
      .reduce((a, t) => a + transactionEffectForLocation(t, l), 0);
    return sum + base + tx;
  }, 0);
}
function monthKey(date){return String(date||'').slice(0,7);}
function monthlyClosingFor(dateOrMonth){
  const month=monthKey(dateOrMonth);
  return (state.monthlyClosings||[]).find(row=>row.month===month&&row.status==='closed')||null;
}
function isMonthClosed(dateOrMonth){return !!monthlyClosingFor(dateOrMonth);}
function ensureMonthOpen(dateOrMonth,action='거래 처리'){
  const closing=monthlyClosingFor(dateOrMonth);
  if(!closing)return true;
  alert(`${closing.month}은(는) 월 마감이 완료되어 ${action}할 수 없습니다.\n월별 마감 메뉴에서 재오픈한 뒤 처리하세요.`);
  return false;
}

function inventorySummary() {
  let totalStock = 0, totalCurrent = 0, totalUse = 0, totalOver = 0, loc = {};
  getLocations().forEach(l => loc[l] = {stock:0,current:0,in:0,use:0,prepaid:0,recovery:0});

  state.products.forEach(p => getLocations().forEach(l => {
    const c = stockCell(p, l);
    loc[l].stock += Number(c.stock || 0);
    const cur = currentQty(p, l);
    loc[l].current += cur;
    totalStock += Number(c.stock || 0);
    totalCurrent += cur;
  }));

  state.transactions.forEach(t => {
    const q = Number(t.qty || 0);
    if(t.type === '입고' && loc[t.location]) loc[t.location].in += q;
    if(t.type === '사용' && loc[t.location]) {
      loc[t.location].use += q;
      totalUse += q;
    }
    if(t.type === '선납') {
      if(loc[t.location]) loc[t.location].prepaid += q;
    }
    if(t.type === '회수') {
      if(loc[t.location]) loc[t.location].recovery += q;
    }
  });

  totalOver = state.overuses.filter(o => o.status !== '정리완료').reduce((a,o) => a + Number(o.qty || 0), 0);
  return {totalStock,totalCurrent,totalUse,totalOver,loc};
}
function monthlyPeriodSummary(month){
  const selected=/^\d{4}-\d{2}$/.test(month||'')?month:today().slice(0,7);
  const [year,mon]=selected.split('-').map(Number),start=`${selected}-01`,end=`${selected}-${String(new Date(year,mon,0).getDate()).padStart(2,'0')}`;
  const locations=getLocations(),loc=Object.fromEntries(locations.map(l=>[l,{stock:0,current:0,in:0,use:0,prepaid:0,recovery:0}]));
  let totalStock=0,totalCurrent=0,totalUse=0,totalOver=0,salesAmount=0,cost=0,transactionCount=0,unpricedItems=0;
  const byLocationValue=Object.fromEntries(locations.map(l=>[l,0]));
  state.products.forEach(p=>{
    let hasClosing=false;
    locations.forEach(l=>{
      const productTx=(state.transactions||[]).filter(t=>t.productId===p.id);
      const opening=Number(stockCell(p,l).stock||0)+productTx.filter(t=>t.date<start).reduce((a,t)=>a+transactionEffectForLocation(t,l),0);
      const closing=opening+productTx.filter(t=>t.date>=start&&t.date<=end).reduce((a,t)=>a+transactionEffectForLocation(t,l),0);
      loc[l].stock+=opening;loc[l].current+=closing;totalStock+=opening;totalCurrent+=closing;
      byLocationValue[l]+=closing*purchasePrice(p);if(closing!==0)hasClosing=true;
    });
    if(hasClosing&&purchasePrice(p)<=0)unpricedItems++;
  });
  const periodTransactions=(state.transactions||[]).filter(t=>t.date>=start&&t.date<=end);
  transactionCount=periodTransactions.length;
  periodTransactions.forEach(t=>{
    const q=Number(t.qty||0),target=loc[t.location];
    if(t.type==='입고'&&target)target.in+=q;
    if(['사용','과사용'].includes(t.type)&&target){target.use+=q;totalUse+=q;const p=productById(t.productId);salesAmount+=q*Number(getHospitalPrice(t.productId,t.location)||0);cost+=q*purchasePrice(p||{});}
    if(t.type==='선납'&&target)target.prepaid+=q;
    if(t.type==='회수'&&target)target.recovery+=q;
  });
  totalOver=(state.overuses||[]).filter(o=>o.date>=start&&o.date<=end&&o.status!=='정리완료').reduce((a,o)=>a+Number(o.qty||0),0);
  const closed=monthlyClosingFor(selected);
  if(closed){
    const closedLoc=Object.fromEntries(locations.map(l=>[l,{stock:0,current:0,in:0,use:0,prepaid:0,recovery:0}])),closedValues=Object.fromEntries(locations.map(l=>[l,0]));
    (closed.lines||[]).forEach(row=>{if(!closedLoc[row.location])closedLoc[row.location]={stock:0,current:0,in:0,use:0,prepaid:0,recovery:0};const x=closedLoc[row.location];x.stock+=Number(row.openingQty||0);x.current+=Number(row.closingQty||0);x.in+=Number(row.incomingQty||0);x.use+=Number(row.useQty||0);x.prepaid+=Number(row.prepaidQty||0);x.recovery+=Number(row.recoveryQty||0);closedValues[row.location]=(closedValues[row.location]||0)+Number(row.inventoryValue||0);});
    const closedTotalValue=Object.values(closedValues).reduce((a,v)=>a+v,0),closedOffice=closedValues['사무실']||0;
    return {month:selected,start,end,locations,loc:closedLoc,totalStock:Object.values(closedLoc).reduce((a,x)=>a+x.stock,0),totalCurrent:Number(closed.summary?.closingQty||0),totalUse:Object.values(closedLoc).reduce((a,x)=>a+x.use,0),totalOver,transactionCount:Number(closed.transactionCount||0),salesAmount:Number(closed.summary?.salesAmount||0),cost:Number(closed.summary?.cost||0),margin:Number(closed.summary?.margin||0),values:{byLocation:closedValues,total:closedTotalValue,office:closedOffice,hospital:closedTotalValue-closedOffice,unpricedItems:(closed.issues||[]).filter(x=>String(x.message||'').includes('매입단가')).length},transactions:periodTransactions,closed:true};
  }
  const totalValue=Object.values(byLocationValue).reduce((a,v)=>a+v,0),officeValue=byLocationValue['사무실']||0,hospitalValue=totalValue-officeValue;
  return {month:selected,start,end,locations,loc,totalStock,totalCurrent,totalUse,totalOver,transactionCount,salesAmount,cost,margin:salesAmount-cost,values:{byLocation:byLocationValue,total:totalValue,office:officeValue,hospital:hospitalValue,unpricedItems},transactions:periodTransactions};
}
function salePrice(p, hospital) { return Number((p.salePrices||{})[hospital] || (p.salePrices||{})['기타'] || 0); }
function purchasePrice(p) { return Number(p.purchasePrice||0); }
function readWorkbook(file, cb) { const reader=new FileReader(); reader.onload=e=>{ try{const wb=XLSX.read(new Uint8Array(e.target.result),{type:'array'}); const ws=wb.Sheets[wb.SheetNames[0]]; cb(XLSX.utils.sheet_to_json(ws,{defval:''}));}catch(error){console.error('Excel read failed',error);alert('엑셀 파일을 읽지 못했습니다. 업로드 샘플 양식인지 확인하세요.');} }; reader.onerror=()=>alert('엑셀 파일을 읽지 못했습니다.'); reader.readAsArrayBuffer(file); }
function updateNav() { const page=location.pathname.split('/').pop()||'index.html'; document.querySelectorAll('.page-link').forEach(a=>{ if((a.getAttribute('href')||'').split('?')[0]===page) a.classList.add('active'); }); }
const DK_PAGE_VERSION='1234';
const DK_MENU_DEFS=[
  ['dashboard','Dashboard','index.html'],['transactions','거래관리','transaction.html'],['inventory','재고관리','inventory.html'],
  ['products','품목 Master','master.html'],['hospitals','거래처 Master','hospital.html'],['hospitalPrices','병원별 판매단가','hospital_price.html'],
  ['prices','단가관리','price.html'],['monthlyClose','월별 마감','monthly_close.html'],['reports','보고서','report.html'],['audit','재고 감사','audit.html'],['settings','환경설정','settings.html']
];
const DK_ROLE_LABELS={admin:'관리자',inventory:'재고담당',sales:'영업담당',viewer:'조회전용'};
const DK_DEFAULT_ROLE_ACCESS={
  admin:['dashboard','transactions','inventory','products','hospitals','hospitalPrices','prices','monthlyClose','reports','audit','settings'],
  inventory:['dashboard','transactions','inventory','products','hospitals','monthlyClose','reports','audit'],
  sales:['dashboard','transactions','inventory','hospitals','hospitalPrices','prices','monthlyClose','reports'],
  viewer:['dashboard','inventory','reports']
};
const DK_MENU_ICONS={dashboard:'📊',transactions:'🧾',inventory:'📦',products:'📁',hospitals:'🏥',hospitalPrices:'🏷️',prices:'💰',monthlyClose:'🗓️',reports:'📈',audit:'🔍',settings:'⚙️'};
function ensureNavigationMenu(){
  const nav=document.querySelector('.nav');if(!nav)return;
  DK_MENU_DEFS.forEach(([key,label,href])=>{
    let link=[...nav.querySelectorAll('.page-link')].find(a=>(a.getAttribute('href')||'').split('?')[0].toLowerCase()===href);
    if(!link){link=document.createElement('a');link.className='page-link';nav.appendChild(link);}
    link.href=`${href}?v=${DK_PAGE_VERSION}`;
    link.textContent=`${DK_MENU_ICONS[key]||''} ${label}`.trim();
  });
  DK_MENU_DEFS.forEach(([, ,href])=>{const link=[...nav.querySelectorAll('.page-link')].find(a=>(a.getAttribute('href')||'').split('?')[0].toLowerCase()===href);if(link)nav.appendChild(link);});
}
function getRoleAccess(role){
  const configured=state?.settings?.roleMenuAccess?.[role];
  const list=Array.isArray(configured)?configured:DK_DEFAULT_ROLE_ACCESS[role]||DK_DEFAULT_ROLE_ACCESS.viewer;
  return role==='admin'?DK_DEFAULT_ROLE_ACCESS.admin:[...new Set(list)].filter(key=>key!=='settings');
}
function currentMenuKey(){
  let page=(location.pathname.split('/').pop()||'index.html').toLowerCase();
  if(page==='dashboard.html')page='index.html';
  return DK_MENU_DEFS.find(x=>x[2]===page)?.[0]||'';
}
function applyRoleAccess(profile){
  if(!profile)return;
  const role=profile.role||'viewer',allowed=new Set(getRoleAccess(role));
  document.querySelectorAll('.nav .page-link').forEach(link=>{
    let href=(link.getAttribute('href')||'').split('?')[0].toLowerCase();if(href==='dashboard.html')href='index.html';
    const key=DK_MENU_DEFS.find(x=>x[2]===href)?.[0];
    link.hidden=!!key&&!allowed.has(key);
  });
  const key=currentMenuKey();
  if(key&&!allowed.has(key)){
    const first=DK_MENU_DEFS.find(x=>allowed.has(x[0]));
    alert(`${DK_ROLE_LABELS[role]||role} 권한으로는 이 메뉴에 접근할 수 없습니다.`);
    location.replace(first?.[2]||'login.html');
  }
}
async function commonInit() {
  ensureNavigationMenu();
  updateNav();
  rememberLastPage();
  const rf=byId('restoreFile'); if(rf) rf.onchange=restoreBackup;
  installCloudControls();
  if(window.DKCloud){
    try{
      const boot=await DKCloud.bootstrap();
      if(boot?.remote?.state_data){
        const mainRemoteState=migrateState(boot.remote.state_data);
        const localHasPendingChanges=!!state.meta?.cloudDirtyAt;
        let protectedCloudState=null;
        const backups=Array.isArray(boot.remote.backup_states)?[...boot.remote.backup_states].reverse():[];
        backups.forEach(row=>{if(row?.state_data)protectedCloudState=protectedCloudState?mergeStateWithoutLoss(protectedCloudState,migrateState(row.state_data)):migrateState(row.state_data);});
        protectedCloudState=protectedCloudState?mergeStateWithoutLoss(protectedCloudState,mainRemoteState):mainRemoteState;
        let finalState=protectedCloudState;
        if(localHasPendingChanges||importantStateScore(state)>0)finalState=mergeStateWithoutLoss(protectedCloudState,state);
        const recoveredData=importantStateScore(finalState)>importantStateScore(mainRemoteState);
        const syncAt=new Date().toISOString();
        finalState.meta=Object.assign({},finalState.meta||{},{lastCloudSyncAt:boot.remote.updated_at||syncAt,cloudDirtyAt:(recoveredData||localHasPendingChanges)?syncAt:''});
        state=finalState;
        window.state=state;
        localStorage.setItem(STORE_KEY,JSON.stringify(state));
        window.dispatchEvent(new CustomEvent('dk-state-updated',{detail:{source:recoveredData?'cloud-snapshot-recovery':'cloud'}}));
        if(recoveredData||localHasPendingChanges){
          DKCloud.queuePush(state,recoveredData?'bootstrap-snapshot-recovery':'bootstrap-pending-local');
        }
      } else if(boot?.mode==='cloud') DKCloud.queuePush(state,'bootstrap-first-upload');
      applyRoleAccess(DKCloud.status.profile);
    }catch(e){ console.error(e); }
  }
  renderResetSummary();
}
function installCloudControls(){
  const top=document.querySelector('.top');
  const actions=document.querySelector('.top .actions');
  if(!top || !actions) return;

  // v11.1 공통 헤더: 페이지 정보 / 로그인 정보 / 도구 모음의 3개 역할을 분리합니다.
  const pageInfo=top.firstElementChild;
  if(pageInfo) pageInfo.classList.add('top-page-info');
  top.classList.add('app-header');
  actions.classList.add('top-tools','header-tools-hidden');
  top.classList.add('header-account-only');

  let userArea=top.querySelector('.top-user-area');
  if(!userArea){
    userArea=document.createElement('div');
    userArea.className='top-user-area';
    top.insertBefore(userArea, actions);
  }

  let st=byId('cloudStatus');
  if(!st){
    st=document.createElement('span');
    st.id='cloudStatus';
    st.className='cloud-status';
    st.textContent='☁ Cloud 확인';
  }
  let user=byId('cloudUser');
  if(!user){
    user=document.createElement('span');
    user.id='cloudUser';
    user.className='cloud-user';
  }
  let out=byId('cloudLogout');
  if(!out){
    out=document.createElement('button');
    out.id='cloudLogout';
    out.className='btn header-logout';
    out.textContent='로그아웃';
    out.onclick=()=>window.DKCloud?.signOut();
  }
  userArea.append(user,out);

  // 자동저장 상태는 작업 도구 오른쪽 끝에 고정합니다.
  const autosave=byId('autosaveStatus');
  const settingsStatus=byId('settingsCloudStatusArea');
  if(settingsStatus){settingsStatus.append(st);if(autosave)settingsStatus.append(autosave);}
  const isSettingsPage=(location.pathname.split('/').pop()||'index.html').toLowerCase()==='settings.html';
  // 업무 메뉴에서는 도구 영역 자체를 제거해 CSS 캐시나 우선순위가 버튼을 다시 표시하지 못하게 합니다.
  if(!isSettingsPage)actions.remove();

  const paint=(d)=>{
    const st=byId('cloudStatus'), user=byId('cloudUser');
    if(st){
      st.className='cloud-status';
      if(!d.configured){st.textContent='☁ Local 모드';}
      else if(!d.online){st.textContent='☁ 오프라인 · 로컬저장';st.classList.add('offline');}
      else if(d.lastError){st.textContent='☁ 동기화 오류';st.classList.add('error');}
      else if(d.syncing){st.textContent='☁ 동기화 중';st.classList.add('syncing');}
      else {st.textContent='☁ Cloud 연결';}
    }
    if(user){
      user.textContent=d.profile?.display_name||d.profile?.username||d.email||'';
      user.title=[d.profile?.display_name,d.profile?.username||d.email].filter(Boolean).join(' · ');
    }
    applyRoleAccess(d.profile);
  };
  window.addEventListener('dk-cloud-status',e=>paint(e.detail));
  if(window.DKCloud) paint(DKCloud.status);
}
window.DK_MENU_DEFS=DK_MENU_DEFS;window.DK_ROLE_LABELS=DK_ROLE_LABELS;window.DK_DEFAULT_ROLE_ACCESS=DK_DEFAULT_ROLE_ACCESS;window.getRoleAccess=getRoleAccess;
document.addEventListener('DOMContentLoaded', commonInit);
window.addEventListener('dk-cloud-push-success',e=>{
  try{
    if(e.detail?.stateData)state=migrateState(e.detail.stateData);
    state.meta=Object.assign({},state.meta||{},{cloudDirtyAt:'',lastCloudSyncAt:e.detail?.updatedAt||new Date().toISOString()});
    window.state=state;
    localStorage.setItem(STORE_KEY,JSON.stringify(state));
    window.dispatchEvent(new CustomEvent('dk-state-updated',{detail:{source:'cloud-save-confirmed'}}));
  }catch(error){console.error('Cloud sync marker failed',error);}
});

function compareHospitalCode(a,b){
  const aCode=String(a?.code||'').trim(),bCode=String(b?.code||'').trim();
  if(!aCode&&bCode)return 1;if(aCode&&!bCode)return -1;
  const codeOrder=aCode.localeCompare(bCode,'ko',{numeric:true,sensitivity:'base'});
  return codeOrder||String(a?.name||'').localeCompare(String(b?.name||''),'ko',{numeric:true,sensitivity:'base'});
}
function sortHospitalMaster(){if(!Array.isArray(state.hospitals))state.hospitals=[];state.hospitals.sort(compareHospitalCode);return state.hospitals;}
function ensureHospitalState(){ if(!state.hospitals||!Array.isArray(state.hospitals)){state.hospitals=HOSPITALS.map((name,i)=>({code:`H${String(i+1).padStart(3,'0')}`,name,manager:'',phone:'',address:'',memo:''}));} sortHospitalMaster(); if(!state.lots||!Array.isArray(state.lots)){state.lots=[];} }
function hospitalOptions(select,includeAll=false){ensureHospitalState(); if(!select)return; select.innerHTML=(includeAll?'<option value="">전체</option>':'')+sortHospitalMaster().map(h=>`<option value="${h.name}">${h.name}</option>`).join('');}
function erpInit(){ensureHospitalState();}
document.addEventListener('DOMContentLoaded',erpInit);

/* ===== v6 Hospital Price Extension ===== */
function ensureV6State(){
  if(!state.hospitals || !Array.isArray(state.hospitals)){
    state.hospitals = HOSPITALS.map((name, idx)=>({
      code:`H${String(idx+1).padStart(3,'0')}`,
      name, manager:'', phone:'', address:'', memo:''
    }));
  }
  if(!state.hospitalPrices || !Array.isArray(state.hospitalPrices)){
    state.hospitalPrices = [];
  }
  // migrate legacy product salePrices to hospitalPrices
  state.products.forEach(p=>{
    p.defaultSalePrice = Number(p.defaultSalePrice || p.salePrice || p.salePrices?.['기타'] || 0);
    if(p.salePrices){
      Object.entries(p.salePrices).forEach(([hospital, price])=>{
        if(price === undefined || price === null || Number(price) === 0) return;
        const exists = state.hospitalPrices.find(x=>x.productId===p.id && x.hospitalName===hospital);
        if(!exists) state.hospitalPrices.push({hospitalName:hospital, productId:p.id, salePrice:Number(price||0)});
      });
      // Keep legacy object only for backward compatibility, but v6 UI no longer writes it.
    }
  });
}
function getHospitalList(){
  ensureV6State();
  return sortHospitalMaster();
}
function hospitalOptions(select, includeAll=false){
  ensureV6State();
  if(!select) return;
  select.innerHTML=(includeAll?'<option value="">전체</option>':'')+sortHospitalMaster().map(h=>`<option value="${h.name}">${h.name}</option>`).join('');
}
function getHospitalPrice(productId, hospitalName){
  ensureV6State();
  const row = state.hospitalPrices.find(x=>x.productId===productId && x.hospitalName===hospitalName);
  if(row) return Number(row.salePrice||0);
  const p = productById(productId);
  return Number(p?.defaultSalePrice || p?.salePrice || p?.salePrices?.['기타'] || 0);
}
function setHospitalPrice(productId, hospitalName, salePrice){
  ensureV6State();
  let row = state.hospitalPrices.find(x=>x.productId===productId && x.hospitalName===hospitalName);
  if(!row){
    row = {productId, hospitalName, salePrice:0};
    state.hospitalPrices.push(row);
  }
  row.salePrice = Number(salePrice || 0);
}
function salePrice(p, hospital){
  if(!p) return 0;
  return getHospitalPrice(p.id, hospital || '기타');
}
function defaultSalePrice(p){
  return Number(p?.defaultSalePrice || p?.salePrice || p?.salePrices?.['기타'] || 0);
}
document.addEventListener('DOMContentLoaded',()=>{ ensureV6State(); setupAutoDraft(); rememberLastPage(); });
